from collections import Counter
class Solution:
    def findPairs(self, nums: list[int], k: int) -> int:
        if k<0:return 0
        c=Counter(nums)
        if k==0:return sum(v>1 for v in c.values())
        return sum(x+k in c for x in c)

class Codec:
    def __init__(self):
        self.url_to_id={};self.id_to_url={};self.next_id=1
    def encode(self, longUrl: str) -> str:
        if longUrl not in self.url_to_id:
            key=str(self.next_id);self.next_id+=1
            self.url_to_id[longUrl]=key;self.id_to_url[key]=longUrl
        return 'http://tinyurl.com/'+self.url_to_id[longUrl]
    def decode(self, shortUrl: str) -> str:
        return self.id_to_url[shortUrl.rsplit('/',1)[-1]]

class Solution:
    def complexNumberMultiply(self, num1: str, num2: str) -> str:
        def parse(s):
            a,b=s[:-1].split('+');return int(a),int(b)
        a,b=parse(num1);c,d=parse(num2)
        return f'{a*c-b*d}+{a*d+b*c}i'

class Solution:
    def convertBST(self, root):
        total=0
        def dfs(n):
            nonlocal total
            if not n:return
            dfs(n.right);total+=n.val;n.val=total;dfs(n.left)
        dfs(root);return root

class Solution:
    def findMinDifference(self, timePoints: list[str]) -> int:
        if len(timePoints)>1440:return 0
        vals=sorted(int(t[:2])*60+int(t[3:]) for t in timePoints)
        ans=1440+vals[0]-vals[-1]
        for a,b in zip(vals,vals[1:]):ans=min(ans,b-a)
        return ans

class Solution:
    def singleNonDuplicate(self, nums: list[int]) -> int:
        lo,hi=0,len(nums)-1
        while lo<hi:
            mid=(lo+hi)//2
            if mid%2:mid-=1
            if nums[mid]==nums[mid+1]:lo=mid+2
            else:hi=mid
        return nums[lo]

class Solution:
    def reverseStr(self, s: str, k: int) -> str:
        a=list(s)
        for i in range(0,len(a),2*k):a[i:i+k]=reversed(a[i:i+k])
        return ''.join(a)

from collections import deque
class Solution:
    def updateMatrix(self, mat: list[list[int]]) -> list[list[int]]:
        m,n=len(mat),len(mat[0]);dist=[[-1]*n for _ in range(m)];q=deque()
        for r in range(m):
            for c in range(n):
                if mat[r][c]==0:dist[r][c]=0;q.append((r,c))
        while q:
            r,c=q.popleft()
            for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                if 0<=nr<m and 0<=nc<n and dist[nr][nc]<0:dist[nr][nc]=dist[r][c]+1;q.append((nr,nc))
        return dist

class Solution:
    def diameterOfBinaryTree(self, root):
        best=0
        def height(n):
            nonlocal best
            if not n:return 0
            l=height(n.left);r=height(n.right);best=max(best,l+r)
            return 1+max(l,r)
        height(root);return best
